function renderIntro(){
  const link = (id, label) => byId[id] ? `<a href="#item/${esc(id)}">${esc(label || byId[id].n)}</a>` : '';
  const STEPS = [
    ["Today, someone else vouches for you", "Online, your identity usually lives with someone else: an email provider, a social network, a certificate authority. If they make a mistake, get breached or lock you out, the people who trusted you through them can no longer be sure it is you. KERI, the Key Event Receipt Infrastructure, was designed so that no such middleman is needed.", link('kerione-keri-white-paper', 'the KERI white paper')],
    ["KERI starts with keys only you hold", "You create a pair of cryptographic keys on your own device, and your identifier is derived from the public key itself: it is self-certifying. Nobody issues it, nobody registers it, and nobody can take it away. Anyone can check that a signature came from the holder of that identifier without asking a company in the middle.", link('papers-keri-for-muggles', 'KERI for Muggles')],
    ["Every change goes in a signed log", "Whenever something about your keys changes, you sign an event and append it to your key event log. Each event is chained to the one before it. Anyone can replay the log from the first event and learn which keys are in charge today, and nothing in it can be altered afterwards without breaking the chain.", link('hitchhikers-guide', "the hitchhiker's guide to KERI")],
    ["You plan your next key in advance", "When you create your keys, you also commit to a fingerprint of the next ones, a step called pre-rotation. If your current key is ever stolen, you rotate to the next one, and the thief cannot stop you or keep pretending to be you, because the next key was never exposed while the current one was in use.", link('kerisuite-glossary', 'the KERI Suite glossary')],
    ["Witnesses keep everyone honest", "Your log is shared with witnesses you choose, and each witness signs a receipt for every event. Watchers compare the copies, so if anyone ever shows two different versions of your history, the duplicity is caught. Digital credentials, like the verifiable LEI that GLEIF issues to organizations, are built on identifiers that work this way.", link('vlei-trainings', 'the vLEI training notebooks')]];
  $('#p-intro').innerHTML = crumbs('What is KERI?') + `<p class="eyebrow">For the newcomer · about ten minutes</p><h1>What is KERI, in five steps</h1><p class="lede">The idea behind the suite, one step at a time, in plain words. Each step points at a card to go deeper. The five steps follow the prototype Janet Gonzales drew for this site on 3 November 2026.</p>
  ${STEPS.map(([h, body, more], i) => `<div class="intro-step"><div class="num">${i + 1}</div><div><h2 style="margin:0 0 6px">${esc(h)}</h2><p style="margin:0">${esc(body)}</p>${more ? `<p class="note" style="margin:6px 0 0">Go deeper: ${more}</p>` : ''}</div></div>`).join('')}
  <div class="grid2"><div class="panel"><h3>Where next</h3><p><a href="#role/newcomer"><b>Start as a newcomer</b></a>: the questions a newcomer brings, and the first four cards to read.</p><p><button class="link" data-go="tutorials">Tutorials and reading paths</button>: an hour, a day, a week.</p></div><div class="panel"><h3>The words</h3><p>KERI, the Key Event Receipt Infrastructure, is the identifier layer. ACDC, Authentic Chained Data Containers, are the credentials built on it. CESR, the Composable Event Streaming Representation, is how the events and credentials are written. The vLEI is GLEIF's credential for organizations, the suite in production.</p></div></div>${strip('intro')}`;
}
